// Target: 0x00222E58 StartFlyby__22kellyslater_controller
// Released source: KS/SRC/ks/kellyslater_controller.cpp

class singleton {
public:
    static singleton *s_inst;
};

class os_developer_options : public singleton {
public:
    enum flags_t { FLAG_NOFLYBY = 88, FLAG_MAKE_MOVIE = 89 };
    char _pad[352];
    int flags[2];
    static os_developer_options *inst() { return (os_developer_options *)s_inst; }
    bool is_flagged(flags_t _flag) const { return flags[_flag - FLAG_NOFLYBY]; }
};

class game_camera {};
class flyby_camera : public game_camera {
public:
    bool load();
    void start();
};

class entity {
public:
    virtual void set_visible(bool a);
};

class game {
public:
    char _pad[552];
protected:
    int beachid;
public:
    int get_beach_id(void) { return beachid; }
};
extern game *g_game_ptr;

enum { BEACH_OPENSEA = 24 };

struct debug_info_t {
    bool dump_frame_info : 1;
    bool dump_threads : 1;
    bool render_spheres : 1;
    bool turtle_watch : 1;
    bool halt_on_asserts : 1;
    bool stay_halted : 1;
    bool simulate32meg : 1;
    bool assert_screen : 1;
    bool mem_free_screen : 1;
};
extern debug_info_t g_debug;

class IGOFrontEnd {
public:
    void SetDisplay(bool on);
};
class FEManager {
public:
    IGOFrontEnd *IGO;
};
extern FEManager frontendmanager;

class kellyslater_controller {
public:
    enum { SUPER_STATE_FLYBY = 1, STATE_FLYBY = 10 };
    char _pad0[12];
    entity *owner;
    char _pad1[32];
    int state;
    int last_state;
    int super_state;
    char _pad2[3596];
    entity *my_board_model;
    char _pad3[2784];
    bool exit_state;
    char _pad4[504];
    bool flyby_first;
    char _pad5[96];
    flyby_camera *flyby_cam_ptr;

    entity *get_owner() const { return owner; }
    void SetPlayerCamera(game_camera *cam);
    bool StartFlyby();
};

//  Set up everything for a flyby of the beach.
bool kellyslater_controller::StartFlyby()
{
	//  Check to make sure that the user is allowing flybys.
	if (os_developer_options::inst()->is_flagged (os_developer_options::FLAG_NOFLYBY))
		return false;

	if (!flyby_cam_ptr->load())  //   Don't do anything if the file isn't there.
		return false;

	flyby_cam_ptr->start();
	SetPlayerCamera(flyby_cam_ptr);

	if (os_developer_options::inst()->is_flagged (os_developer_options::FLAG_MAKE_MOVIE) || 
		g_game_ptr->get_beach_id () == BEACH_OPENSEA)
	{
		g_debug.halt_on_asserts = 0;
		frontendmanager.IGO->SetDisplay(false);
	}

	exit_state = true;

	super_state = SUPER_STATE_FLYBY;
	state = STATE_FLYBY;

	get_owner()->set_visible(false);
	my_board_model->set_visible(false);
	flyby_first = true;

	return true;
}
